CREATE TABLE `T_CK_CNT` (
  `CNT_ID` varchar(35) NOT NULL COMMENT 'CONTAINER ID - UUID',
  `CNT_NO` varchar(255) NOT NULL COMMENT 'CONTAINER NUMBER',
  `CNT_ISO_CODE` varchar(35) DEFAULT NULL COMMENT 'ISO 6346 CODE - 20PF : 45R9 : 42G0',
  `CNT_IMO_CODE` varchar(35) DEFAULT NULL COMMENT 'IMO CODE - THE IMO CHARACTERIZES DANGEROUS GOODS INTO NINE CLASSES. EXAMPLE GASES IMO 1, EXPLOSIVES IMO 2 AND CORROSIVE SUBSTANCES IMO4',
  `CNT_TYPE` varchar(35) DEFAULT NULL COMMENT 'CONTAINER TYPE - REFERENCE T_CK_MST_CNT_TYPE:CNTT_ID',
  `CNT_SIZE` varchar(35) DEFAULT NULL COMMENT 'CONTAINER SIZE - REFERENCE T_CK_MST_CNT_SIZE:CNTZ_ID',
  `CNT_HEIGHT` mediumint DEFAULT '0' COMMENT 'CONTAINER HEIGHT (M)',
  `CNT_WEIGHT` mediumint DEFAULT '0' COMMENT 'CONTAINER WEIGHT (KG)',
  `CNT_BRUTO` mediumint DEFAULT '0' COMMENT 'CONTAINER BRUTO (KG)',
  `CNT_FULL_EMPTY_INDR` char(1) DEFAULT 'F' COMMENT 'CONTAINER FULL INDCIATOR (FCL/LCL) - F : E',
  `CNT_IMDG` char(1) DEFAULT 'N' COMMENT 'INTERNATIONAL MARITIME DANGEROUS GOODS - Y : N',
  `CNT_IMDG_UN_NO` varchar(255) DEFAULT NULL COMMENT 'IMDG UN NO - 0030',
  `CNT_IMDG_IMDG_CLASS` tinyint DEFAULT '0' COMMENT 'IMDG CLASS - 1:2:3...9',
  `CNT_IMDG_VALUE` varchar(255) DEFAULT NULL COMMENT 'EXTENSION OF IMDG CLASS - 1b mean class is 1.1B',
  `CNT_RFR_INDR` char(1) DEFAULT 'Y' COMMENT 'CONTAINER REEFER INDICATOR - Y : N',
  `CNT_RFR_REQUIRED_VOLTAGE` smallint DEFAULT '0' COMMENT 'CONTAINER REEFER REQUIRED VOLTAGE',
  `CNT_RFR_REQUIRED_TEMPERATURE` decimal(5,2) DEFAULT '0.00' COMMENT 'CONTAINER REEFER REQUIRED TEMPERATURE',
  `CNT_RFR_START_PLUG` datetime DEFAULT NULL COMMENT 'CONTAINER REEFER PLUG IN DATETIME',
  `CNT_RFR_STOP_PLUG` datetime DEFAULT NULL COMMENT 'CONTAINER REEFER PLUG OUT DATETIME',
  `CNT_OOG_TOP` mediumint DEFAULT '0' COMMENT 'OUT OF GUAGE CARGO TOP (M)',
  `CNT_OOG_LEFT` mediumint DEFAULT '0' COMMENT 'OUT OF GUAGE CARGO LEFT (M)',
  `CNT_OOG_RIGHT` mediumint DEFAULT '0' COMMENT 'OUT OF GUAGE CARGO RIGHT (M)',
  `CNT_SEAL_NO` varchar(255) DEFAULT NULL COMMENT 'CONTAINER SEAL NUMBER',
  `CNT_STACKING` datetime DEFAULT NULL COMMENT 'CONTAINER STACKING DATETIME',
  `CNT_GATE_IN` datetime DEFAULT NULL COMMENT 'CONTAINER GATE IN TIME',
  `CNT_GATE_OUT` datetime DEFAULT NULL COMMENT 'CONTAINER GATE OUT TIME',
  `CNT_LOCATION` varchar(255) DEFAULT NULL COMMENT 'CONTAINER LOCATION - IMPORT_AREA:TRUCK_PAD:STACKING_YARD:EXPORT_AREA:EXPORT_STACKING_YARD',
  `CNT_VESSEL_NO` varchar(255) DEFAULT NULL COMMENT 'CONTAINER VESSEL OFFICAL NO (VON) - CG002972',
  `CNT_VESSEL_NAME` varchar(255) DEFAULT NULL COMMENT 'CONTAINER VESSEL NAME - EVERGREEN TERESA',
  `CNT_VOYAGE_NO` varchar(255) DEFAULT NULL COMMENT 'CONTAINER VOYAGE NO - V.284',
  `CNT_VESSEL_ETA` datetime DEFAULT NULL COMMENT 'CONTAINER VESSEL ESTIMATED ARRIVAL TIME - 20201001 00:00:00',
  `CNT_VESSEL_ATA` datetime DEFAULT NULL COMMENT 'CONTAINER VESSEL ACTUAL ARRIVAL TIME - 20201001 00:00:00',
  `CNT_VESSEL_ETD` datetime DEFAULT NULL COMMENT 'CONTAINER VESSEL ESTIMATED DEPARTURE TIME - 20201001 00:00:00',
  `CNT_VESSEL_ATD` datetime DEFAULT NULL COMMENT 'CONTAINER VESSEL ACUTAL DEPARTURE TIME - 20201001 00:00:00',
  `CNT_POD` varchar(5) DEFAULT NULL COMMENT 'CONTAINER PORT OF DISCHARGE - REFERENCE T_MST_PORT:PORT_CODE',
  `CNT_POL` varchar(5) DEFAULT NULL COMMENT 'CONTAINER PORT OF LOADING - REFERENCE T_MST_PORT:PORT_CODE',
  `CNT_DT_DISCHARGE` datetime DEFAULT NULL COMMENT 'CONTAINER DISCHARGED DATE',
  `CNT_DT_LOAD` datetime DEFAULT NULL COMMENT 'CONTAINER LOAD DATE',
  `CNT_DANGEROUS_GOOD` char(1) DEFAULT 'N' COMMENT 'CONTAINER CONTENT DANGEROUS',
  `CNT_MARKS_NO` varchar(1024) DEFAULT NULL COMMENT 'CONTAINER CONTENT MARKS AND NUMBER',
  `CNT_NO_PACKAGES` varchar(1024) DEFAULT NULL COMMENT 'CONTAINER NUMBER OF PACKAGES',
  `CNT_DESCRIPTION` mediumtext COMMENT 'CONTAINER DESCRIPTION',
  `CNT_OWNER` varchar(255) DEFAULT NULL COMMENT 'CONTAINER OWNER NAME - ',
  `CNT_TAXID` varchar(255) DEFAULT NULL COMMENT 'CONTAINER OWNER TAX IDENTIFICATION  - NPWP',
  `CNT_SENDER` varchar(255) DEFAULT NULL COMMENT 'CONTAINER SENDER OR EXPORTER NAME - ',
  `CNT_FORWARDER` varchar(255) DEFAULT NULL COMMENT 'CONTAINER FREIGHT FORWARDER NAME - NM_ANGKUT',
  `CNT_CCAC_NO` varchar(255) DEFAULT NULL COMMENT 'CONTAINER CUSTOMS CLEARANCE APPROVAL CERTIFCATE NO (CCP) - SPPB',
  `CNT_BL_AWB_NO` varchar(255) DEFAULT NULL COMMENT 'CONTAINER BL OR AWB NO - ',
  `CNT_STATUS_CUSTOMS` varchar(255) DEFAULT NULL COMMENT 'CONTAINER CUSTOMS CLEARANCE STATUS - ',
  `CNT_STATUS_QUARANTINE` varchar(255) DEFAULT NULL COMMENT 'CONTAINER QUARANTINE CLEARANCE STATUS - ',
  `CNT_DO_LAST_PAID_THRU` datetime DEFAULT NULL COMMENT 'CONTAINER DO LAST PAID THRU DATE - 20201001 00:00:00',
  `CNT_REMARKS` varchar(512) DEFAULT NULL COMMENT 'CONTAINER REMARKS',
  `CNT_STATUS` char(1) DEFAULT NULL COMMENT 'CONTAINER TYPE STATUS',
  `CNT_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `CNT_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `CNT_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `CNT_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`CNT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='CONTAINER TABLE';
