--
-- Table structure for table `T_CK_CP_TXN`
--

DROP TABLE IF EXISTS `T_CK_CP_TXN`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_CP_TXN` (
  `TXN_ID` varchar(35) NOT NULL COMMENT 'TXN ID - UUID',
  `TXN_TYPE` varchar(35) DEFAULT NULL COMMENT 'TXN TYPE - REFERENCE T_CK_CP_MST_TXN_TYPE:TXTY_ID',
  `TXN_STATE` varchar(35) DEFAULT NULL COMMENT 'TXN STATE - REFERENCES T_CK_CP_MST_TXN_STATE:TXST_ID',
  `TXN_SERVICE` varchar(35) DEFAULT NULL COMMENT 'CLICKARGO SERVICES GENERATING TXN - REFERENCE T_CK_MST_SERVICE_TYPE:SVCT_ID',
  `TXN_SERVICE_REF` varchar(35) DEFAULT NULL COMMENT 'TXN REFERENCE - PROVIDED BY INVOKER',
  `TXN_PARAM` mediumtext COMMENT 'REQUEST PARAMS OF TXN - JSON MAP',
  `TXN_REQ` mediumtext COMMENT 'REQUEST BODY OF TXN - JSON OBJECT OF REQUEST BODY',
  `TXN_DT_REQ` datetime DEFAULT NULL COMMENT 'DATE TIME OF TXN REQUEST',
  `TXN_RESP` mediumtext COMMENT 'RESPONSE BODY OF TXN - JSON OBJECT OF RESPONSE BODY',
  `TXN_RESP_CODE` smallint DEFAULT NULL COMMENT 'HTTP RESPONSE CODE',
  `TXN_DT_RESP` datetime DEFAULT NULL COMMENT 'DATE TIME OF TXN RESPONSE',
  `TXN_STATUS` char(1) DEFAULT NULL COMMENT 'RECORD STATUS - A : I',
  `TXN_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `TXN_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `TXN_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `TXN_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`TXN_ID`),
  KEY `FK_CK_CP_TXN_CK_CP_MST_TXN_TYPE` (`TXN_TYPE`),
  KEY `FK_CK_CP_TXN_CK_CP_MST_TXN_STATE` (`TXN_STATE`),
  KEY `FK_CK_CP_TXN_CK_MST_SERVICE_TYPE` (`TXN_SERVICE`),
  CONSTRAINT `FK_CK_CP_TXN_CK_CP_MST_TXN_STATE` FOREIGN KEY (`TXN_STATE`) REFERENCES `T_CK_CP_MST_TXN_STATE` (`TXST_ID`),
  CONSTRAINT `FK_CK_CP_TXN_CK_CP_MST_TXN_TYPE` FOREIGN KEY (`TXN_TYPE`) REFERENCES `T_CK_CP_MST_TXN_TYPE` (`TXTY_ID`),
  CONSTRAINT `FK_CK_CP_TXN_CK_MST_SERVICE_TYPE` FOREIGN KEY (`TXN_SERVICE`) REFERENCES `T_CK_MST_SERVICE_TYPE` (`SVCT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='CP TXN';
/*!40101 SET character_set_client = @saved_cs_client */;

