DROP TABLE IF EXISTS `T_CK_DO`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_DO` (
  `DO_ID` varchar(35) NOT NULL COMMENT 'DO IMPORT ID - UUID',
  `DO_SHIPMENT_TYPE` varchar(35) NOT NULL COMMENT 'DO SHIPMENT TYPE - REFERENCES T_CK_MST_SHIPMENT_TYPE:SHT_ID',
  `DO_SL_ACCN` varchar(35) DEFAULT NULL COMMENT 'SHIPPING LINE ACCOUNT ASSOCIATED WITH DO',
  `DO_CO_ACCN` varchar(35) DEFAULT NULL COMMENT 'CARGO OWNER ACCOUNT ASSOCIATED WITH DO',
  `DO_FF_ACCN` varchar(35) DEFAULT NULL COMMENT 'FREIGHT FORWARDER ACCOUNT ASSOCIATED WITH DO',
  `DO_NOTIFY_ACCN` varchar(35) DEFAULT NULL COMMENT 'NOTIFICATION ACCOUNT ASSOCIATED WITH DO',
  `DO_NO` varchar(255) DEFAULT NULL COMMENT 'DO NUMBER',
  `DO_VESSEL_NO` varchar(255) DEFAULT NULL COMMENT 'DO VESSEL OFFICAL NO (VON) - CG002972',
  `DO_VESSEL_NAME` varchar(255) DEFAULT NULL COMMENT 'DO VESSEL NAME - EVERGREEN TERESA',
  `DO_VESSEL_ETA` datetime DEFAULT NULL COMMENT 'DO VESSEL ESTIMATED ARRIVAL TIME - 20201001',
  `DO_VESSEL_ATA` datetime DEFAULT NULL COMMENT 'DO VESSEL ACTUAL ARRIVAL TIME - 20201001 00:00:00',
  `DO_VESSEL_ETD` datetime DEFAULT NULL COMMENT 'DO VESSEL ESTIMATED DEPARTURE TIME - 20201001',
  `DO_VESSEL_ATD` datetime DEFAULT NULL COMMENT 'DO VESSEL ACTUAL DEPARTURE TIME - 20201001 00:00:00',
  `DO_VOYAGE_NO` varchar(255) DEFAULT NULL COMMENT 'DO VOYAGE NO - V.284',
  `DO_TERMINAL` varchar(255) DEFAULT NULL COMMENT 'DO TERMINAL OF DISCHARGE',
  `DO_POL` varchar(5) DEFAULT NULL COMMENT 'DO PORT OF LOADING - REFERENCE T_MST_PORT:PORT_CODE',
  `DO_POD` varchar(5) DEFAULT NULL COMMENT 'DO PORT OF DISCHARGE - REFERENCE T_MST_PORT:PORT_CODE',
  `DO_NO_CNT` smallint DEFAULT '0' COMMENT 'DO NUMBER OF CONTAINERS',
  `DO_STATE` varchar(35) DEFAULT NULL COMMENT 'DO STATE - REFERENCE T_CK_MST_DO_STATE:DOST_ID',
  `DO_BL_NO` varchar(255) DEFAULT NULL COMMENT 'IMPORT DO BL NUMBER - ',
  `DO_BL_TYPE` varchar(35) DEFAULT NULL COMMENT 'BL TYPE GIVEN BY THE SHIPPING LINE',
  `DO_BL_DOC` varchar(1024) DEFAULT NULL COMMENT 'BL ATTACHMENT PATH REFERENCE FROM SYS_PARAM SETUP',
  `DO_BL` varchar(35) DEFAULT NULL COMMENT 'BL USED TO CLAIM DO - REFERENCE T_CK_DO_BL:BL_ID',
  `DO_DELIVERY` varchar(2048) DEFAULT NULL COMMENT 'DO PLACE OF DELIVERY - ',
  `DO_DEPOT` varchar(2048) DEFAULT NULL COMMENT 'DO RETURN OR COLLECITON DEPOT',
  `DO_DT_PAID_THRU` datetime DEFAULT NULL COMMENT 'DO PAID THRU DATE - 20201001 00:00:00',
  `DO_DT_SUBMIT` datetime DEFAULT NULL COMMENT 'DO SUBMITTED DATE',
  `DO_DT_PAID` datetime DEFAULT NULL COMMENT 'DO PAID DATE',
  `DO_DT_CLAIM` datetime DEFAULT NULL COMMENT 'DO CLAIM DATE',
  `DO_DO_DOC` varchar(1024) DEFAULT NULL COMMENT 'DO ATTACHMENT PATH REFERENCE FROM SYS_PARAM SETUP',
  `DO_STATUS` char(1) DEFAULT NULL COMMENT 'DO STATUS - A : I ',
  `DO_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `DO_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `DO_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `DO_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`DO_ID`),
  KEY `FK_CK_DO_CK_MST_SHIPMENT_TYPE` (`DO_SHIPMENT_TYPE`),
  KEY `FK_CK_DO_CK_MST_DO_STATE` (`DO_STATE`),
  KEY `FK_CK_DO_CK_ACCN1` (`DO_SL_ACCN`),
  KEY `FK_CK_DO_CK_ACCN2` (`DO_CO_ACCN`),
  KEY `FK_CK_DO_CK_ACCN3` (`DO_FF_ACCN`),
  KEY `FK_CK_DO_CK_ACCN4` (`DO_NOTIFY_ACCN`),
  KEY `FK_CK_DO_DO_BL` (`DO_BL`),
  CONSTRAINT `FK_CK_DO_CK_ACCN1` FOREIGN KEY (`DO_SL_ACCN`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_DO_CK_ACCN2` FOREIGN KEY (`DO_CO_ACCN`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_DO_CK_ACCN3` FOREIGN KEY (`DO_FF_ACCN`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_DO_CK_ACCN4` FOREIGN KEY (`DO_NOTIFY_ACCN`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_DO_CK_MST_DO_STATE` FOREIGN KEY (`DO_STATE`) REFERENCES `T_CK_MST_DO_STATE` (`DOST_ID`),
  CONSTRAINT `FK_CK_DO_CK_MST_SHIPMENT_TYPE` FOREIGN KEY (`DO_SHIPMENT_TYPE`) REFERENCES `T_CK_MST_SHIPMENT_TYPE` (`SHT_ID`),
  CONSTRAINT `FK_CK_DO_DO_BL` FOREIGN KEY (`DO_BL`) REFERENCES `T_CK_DO_BL` (`BL_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='DELIVERY ORDER TABLE';
