  `PYL_MERCHANT_BANK` varchar(35) DEFAULT NULL COMMENT 'PAYMENT MERCHANT BANK',
  `PYL_PAYER` varchar(35) DEFAULT NULL COMMENT 'PAYER - REFERENCES T_CORE_ACCN:ACCN_ID',
  `PYL_PAYER_BANK_ACCN` varchar(255) DEFAULT NULL COMMENT 'PAYER BANK ACCOUNT NUMBER',
  `PYL_PAYEE` varchar(35) DEFAULT NULL COMMENT 'PAYEE - REFERENCES T_CORE_ACCN:ACCN_ID',
  `PYL_PAYEE_BANK_ACCN` varchar(255) DEFAULT NULL COMMENT 'PAYER BANK ACCOUNT NUMBER',
  `PYL_AMOUNT` decimal(15,2) DEFAULT '0.00' COMMENT 'PAYEE - REFERENCES T_CORE_ACCN:ACCN_ID',
  `PYL_CCY` varchar(3) DEFAULT NULL COMMENT 'CURRENCY  - REFERENCES T_MST_CURRENCY:CCY_CODE',
  `PYL_BANK_REF` varchar(255) DEFAULT NULL COMMENT 'BANK REFERENCE NUMBER - VA',
  `PYL_PAYMENT_STATE` varchar(35) DEFAULT NULL COMMENT 'PAYMENT STATE - SUCCESS : FAIL : NEW',
  `PYL_STATUS` char(1) DEFAULT NULL COMMENT 'RECORD STATUS - A : I',
  `PYL_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `PYL_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `PYL_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `PYL_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`PYL_ID`),
  KEY `FK_CK_PAYMENT_LEDGER_CK_MST_PAYMENT_TYPE` (`PYL_TYPE`),
  KEY `FK_CK_PAYMENT_LEDGER_CK_MST_SERVICE_TYPE` (`PYL_SERVICE`),
