  KEY `FK_CK_PAYMENT_LEDGER_MST_CCY` (`PYL_CCY`),
  CONSTRAINT `FK_CK_PAYMENT_LEDGER_CK_MST_PAYMENT_TYPE` FOREIGN KEY (`PYL_TYPE`) REFERENCES `T_CK_MST_PAYMENT_TYPE` (`PTY_ID`),
  CONSTRAINT `FK_CK_PAYMENT_LEDGER_CK_MST_SERVICE_TYPE` FOREIGN KEY (`PYL_SERVICE`) REFERENCES `T_CK_MST_SERVICE_TYPE` (`SVCT_ID`),
  CONSTRAINT `FK_CK_PAYMENT_LEDGER_CORE_ACCN1` FOREIGN KEY (`PYL_PAYER`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_PAYMENT_LEDGER_CORE_ACCN2` FOREIGN KEY (`PYL_PAYEE`) REFERENCES `T_CORE_ACCN` (`ACCN_ID`),
  CONSTRAINT `FK_CK_PAYMENT_LEDGER_MST_CCY` FOREIGN KEY (`PYL_CCY`) REFERENCES `T_MST_CURRENCY` (`CCY_CODE`)
