CREATE TABLE `T_CK_RECORD_DATE` (
  `RCD_ID` varchar(35) NOT NULL COMMENT 'DATE  ID - EXP : IMP',
  `RCD_DT_DRFT` datetime DEFAULT NULL COMMENT 'RECORD DRAFT DATE',
  `RCD_DT_START` datetime DEFAULT NULL COMMENT 'RECORD START DATE',
  `RCD_DT_EXPIRY` datetime DEFAULT NULL COMMENT 'RECORD EXPIRY DATE',
  `RCD_DT_SUBMIT` datetime DEFAULT NULL COMMENT 'RECORD SUBMITTED DATE',
  `RCD_DT_COMPLETE` datetime DEFAULT NULL COMMENT 'RECORD COMPLETED DATE',
  `RCD_DT_CANCEL` datetime DEFAULT NULL COMMENT 'RECORD CANCELLED DATE',
  `RCD_DT_REJECT` datetime DEFAULT NULL COMMENT 'RECORD REJECTED DATE',
  `RCD_DT_DELETE` datetime DEFAULT NULL COMMENT 'RECORD DELTED DATE',
  PRIMARY KEY (`RCD_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='RECORD DATE TABLE';
