DROP TABLE IF EXISTS `T_CK_SVC_AUTH_ATTACH`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CK_SVC_AUTH_ATTACH` (
  `ATT_ID` varchar(35) NOT NULL COMMENT 'SERVICE AUTHORIZATION  ATTACHMENT ID - UUID',
  `ATT_SUA` varchar(35) NOT NULL COMMENT 'SERVICE AUTHORIZATION - REFERENCE T_CK_SVC_AUTH:SVAU_ID',
  `ATT_TYPE` varchar(3) NOT NULL COMMENT 'SERVICE AUTHORIZATION ATTACHMENT TYPE - REFERENCE T_MST_ATT_TYPE:MATT_ID',
  `ATT_ACCN_TYPE` varchar(35) NOT NULL COMMENT 'SERVICE AUTHORIZATION ACCN TYPE - REFERENCE T_CK_MST_AUTH_ACCN_TYPE:AUAT_ID',
  `ATT_NAME` varchar(256) DEFAULT NULL COMMENT 'SERVICE AUTHORIZATION NAME',
  `ATT_LOC` varchar(1024) DEFAULT NULL COMMENT 'SERVICE AUTHORIZATION PATH REFERENCE FROM SYS_PARAM SETUP',
  `ATT_STATUS` char(1) DEFAULT NULL COMMENT 'SERVICE AUTHORIZATION STATUS - A : I ',
  `ATT_DT_CREATE` datetime DEFAULT NULL COMMENT 'RECORD CREATED DATE',
  `ATT_UID_CREATE` varchar(35) DEFAULT NULL COMMENT 'RECORD CREATED USER',
  `ATT_DT_LUPD` datetime DEFAULT NULL COMMENT 'RECORD LAST UPDATED DATE',
  `ATT_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'RECORD LAST UPDATED USER',
  PRIMARY KEY (`ATT_ID`),
  KEY `FK_CK_SVC_AUTH_CK_MST_AUTH_ACCN_TYPE` (`ATT_ACCN_TYPE`),
  KEY `FK_CK_SVC_AUTH_CK_SVC_AUTH` (`ATT_SUA`),
  KEY `FK_CK_SVC_AUTH_MST_ATT_TYPE` (`ATT_TYPE`),
