  CONSTRAINT `FK_CK_SVC_AUTH_CK_SVC_AUTH` FOREIGN KEY (`ATT_SUA`) REFERENCES `T_CK_SVC_AUTH` (`SVAU_ID`),
  CONSTRAINT `FK_CK_SVC_AUTH_MST_ATT_TYPE` FOREIGN KEY (`ATT_TYPE`) REFERENCES `T_MST_ATT_TYPE` (`MATT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='SERVICE AUTHORIZATION ATTACHMENT TABLE';
