--
-- Table structure for table `T_CORE_GRANT_ROLE`
--

DROP TABLE IF EXISTS `T_CORE_GRANT_ROLE`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `T_CORE_GRANT_ROLE` (
  `GRNTR_APPS_CODE` varchar(35) NOT NULL COMMENT 'Holds the Application Code the ROLE belongs to',
  `GRNTR_ROLE_ID` varchar(35) NOT NULL COMMENT 'The ROLE ID that was granted with the permission',
  `GRNTR_PERM_ID` varchar(35) NOT NULL COMMENT 'Contains the unique ID of the permission being granted.',
  `GRNTR_STATUS` char(1) NOT NULL COMMENT 'A is active,I is inactive,Default is A',
  `GRNTR_DT_CREATE` datetime NOT NULL COMMENT 'Contains the date where this record is created. Default to CURR_DATE',
  `GRNTR_UID_CREATE` varchar(35) NOT NULL COMMENT 'Contains the User ID that create this record.',
  `GRNTR_DT_LUPD` datetime DEFAULT NULL COMMENT 'Contains the date where this record is last updated.',
  `GRNTR_UID_LUPD` varchar(35) DEFAULT NULL COMMENT 'Contains the User ID that last update this record.',
  PRIMARY KEY (`GRNTR_APPS_CODE`,`GRNTR_ROLE_ID`,`GRNTR_PERM_ID`),
  KEY `FKY__T_CORE_PERM__PERMID_idx` (`GRNTR_PERM_ID`),
  CONSTRAINT `FKY__T_CORE_PERM__PERMID` FOREIGN KEY (`GRNTR_PERM_ID`) REFERENCES `T_CORE_PERM` (`PERM_ID`),
  CONSTRAINT `FKY__T_CORE_ROLE__COMP` FOREIGN KEY (`GRNTR_APPS_CODE`, `GRNTR_ROLE_ID`) REFERENCES `T_CORE_ROLE` (`ROLE_APPSCODE`, `ROLE_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
/*!40101 SET character_set_client = @saved_cs_client */;

